const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

let p = 0;
const N = input[p++];
const M = input[p++];

const cars = input.slice(p, p + N).sort((a, b) => b - a);
p += N;
const factors = input.slice(p, p + M);

// Min-heap of [next slot cost, factor].
const heap = [];

function push(cost, factor) {
  let i = heap.length;
  heap.push([cost, factor]);

  while (i > 0) {
    const parent = (i - 1) >> 1;
    if (heap[parent][0] <= cost) break;
    heap[i] = heap[parent];
    i = parent;
  }
  heap[i] = [cost, factor];
}

function pop() {
  const result = heap[0];
  const last = heap.pop();

  if (heap.length > 0) {
    let i = 0;
    while (true) {
      let child = i * 2 + 1;
      if (child >= heap.length) break;
      if (child + 1 < heap.length && heap[child + 1][0] < heap[child][0]) {
        child++;
      }
      if (heap[child][0] >= last[0]) break;
      heap[i] = heap[child];
      i = child;
    }
    heap[i] = last;
  }

  return result;
}

for (const factor of factors) push(0, factor);

let answer = 0n;

for (let i = 0; i < N; i++) {
  const [cost, factor] = pop();
  answer += BigInt(cars[i]) * BigInt(cost);
  push(cost + factor, factor);
}

console.log(answer.toString());
